INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('66nspez6q31zfbhawejv66nspbyeuaq2', '2025-Q4', 'Dez/2025', '2025-12-11T19:01'::timestamptz, 'Ana Elisa Campos Diaféria', 'ana elisa campos diaferia', 'PHARUS', 'Julio Cienkonog', 7.0, 'Neutro', 10.0, 8.0, 2.0, NULL, NULL, NULL, NULL, NULL, NULL, 'O sistema ainda é muito instável e com informações inconsistentes. A AI não fez a leitura correta dos arquivos importados. Essa instabilidade gera preocupação quanto a segurança das informações.', NULL, 'Se os resultados esperados forem alcançados', 'Tenho gostado muito do atendimento e metodologia, mas não gostei do sistema. Achei que fosse ser mais prático e não fosse demandar tanto tempo e correções.', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', '66nspez6q31zfbhawejv66nspbyeuaq2', 'aba PHARUS da planilha', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_