INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('34kqq8d7174qhdvvdm834kq2ls2moh7b', '2025-Q4', 'Dez/2025', '2025-12-12T11:18'::timestamptz, 'André Luiz Alves Santana', 'andre luiz alves santana', 'PHARUS', NULL, 6.0, 'Detrator', 7.0, 8.0, 5.0, NULL, 'Sim, em grande parte', NULL, NULL, NULL, NULL, 'A minha experiência ainda está muito no início, por este motivo não é possível realizar uma avaliação assertiva. Como sugestão, penso que seria interessante o assessorado poder trazer ideias de investimentos e que estas fossem avaliadas pelo assessor em caráter de urgência.', NULL, 'Resultado, ou seja, quero ter rendimentos compatíveis com aquilo que foi dito que era possível pelo grupo. Neste caso, ficarei até o......', 'Tenho uma boa expectativa com relação ao grupo e desejo muito que tudo dê certo.', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', '34kqq8d7174qhdvvdm834kq2ls2moh7b', 'aba PHARUS da planilha', NULL) ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresenta