INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('1rtty90cjw8fgeqjdieg61rttdimthd3', '2025-Q4', 'Dez/2025', '2025-12-12T17:49'::timestamptz, 'Mirian Cristina Vieira Otoni', 'mirian cristina vieira otoni', 'PHARUS', 'Carlos Serafim', 7.0, 'Neutro', 8.0, 5.0, 2.0, NULL, 'Mais ou menos', NULL, NULL, NULL, NULL, 'Facilitar a forma de registro de fluxo financeiro e investimentos, reduzir a morosidade do processo, colocar o assessor com mais tempo disponível para avaliar com profundidade as particularidades, retorno e acompanhamento do plano de ação.  Espera-se neste nível de investimento ter um assessor mais presente do que por exemplo um do Personalite.', NULL, 'Melhor entendimento de como as coisas serão feitas na prática dado todas as estratégias e objetivos de curto prazo que foram passadas. Não tive esta clareza e tbm um  suporte e acompanhamento mais presente.', 'A percepção no momento é que o assessor está com agenda lotada de clientes e com pouco tempo disponível para realizar as análises, dar suporte, realizar acompanhamento mais de perto e de curto prazo.', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', '1rtty90cjw8fgeqjdieg61rttdimthd3', 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategis