INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('zzjg1qfyrw9hpnzzjg1qbahys125sjr3', '2025-Q4', 'Dez/2025', '2025-12-12T18:59'::timestamptz, 'Vanessa Cristine Marcondes Espindola', 'vanessa cristine marcondes espindola', 'PHARUS', 'João Aliceda', 10.0, 'Promotor', 10.0, 10.0, 4.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Atenciosos e dominam o assunto que se propõe', 'Usar os recursos que já tenho e conseguir de lucro no mínimo o que paguei na consultoria', 'Sem mais, estou satisfeita até o momento', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', 'zzjg1qfyrw9hpnzzjg1qbahys125sjr3', 'aba PHARUS da planilha', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas =